     4→using Nethermind.Core.Specs;
     5→using Nethermind.Int256;
     6→
     7→namespace Nethermind.Core;
     8→
     9→public interface IBaseFeeCalculator
    10→{
    11→    UInt256 Calculate(BlockHeader parent, IEip1559Spec specFor1559);
    12→}
    13→
    14→/// <summary>
    15→/// Calculate <c>BaseFee</c> based on parent <see cref="BlockHeader"/> and <see cref="IEip1559Spec"/>.
    16→/// </summary>
    17→public sealed class DefaultBaseFeeCalculator : IBaseFeeCalculator
    18→{
    19→    public UInt256 Calculate(BlockHeader parent, IEip1559Spec specFor1559)
    20→    {
    21→        UInt256 expectedBaseFee = parent.BaseFeePerGas;
    22→        if (specFor1559.IsEip1559Enabled)
    23→        {
    24→            UInt256 parentBaseFee = parent.BaseFeePerGas;
    25→            long gasDelta;
    26→            UInt256 feeDelta;
    27→            bool isForkBlockNumber = specFor1559.Eip1559TransitionBlock == parent.Number + 1;
    28→            long parentGasTarget = parent.GasLimit / specFor1559.ElasticityMultiplier;
    29→            if (isForkBlockNumber)
    30→                parentGasTarget = parent.GasLimit;
    31→
    32→            if (parent.GasUsed == parentGasTarget)
    33→            {
    34→                expectedBaseFee = parent.BaseFeePerGas;
    35→            }
    36→            else if (parent.GasUsed > parentGasTarget)
    37→            {
    38→                gasDelta = parent.GasUsed - parentGasTarget;
    39→                feeDelta = UInt256.Max(
    40→                    parentBaseFee * (UInt256)gasDelta / (UInt256)parentGasTarget / specFor1559.BaseFeeMaxChangeDenominator,
    41→                    UInt256.One);
    42→                expectedBaseFee = parentBaseFee + feeDelta;
    43→            }
    44→            else
    45→            {
    46→                gasDelta = parentGasTarget - parent.GasUsed;
    47→                feeDelta = parentBaseFee * (UInt256)gasDelta / (UInt256)parentGasTarget / specFor1559.BaseFeeMaxChangeDenominator;
    48→                expectedBaseFee = UInt256.Max(parentBaseFee - feeDelta, 0);
    49→            }
    50→
